sources.en:
classDiagram
    direction LR
    namespace Domain["Domain model"] {
        class Customer {
            +String name
            +placeOrder() Order
        }
        class Order {
            +String id
            +total() Money
        }
        class Payment <<interface>>
        Payment : +authorize() bool
        Customer "1" --> "0..*" Order : Created
        Order --> Payment : Pay
    }
    note for Payment "Isolate payment implementations behind an interface<br>Callers depend only on the payment protocol"
    note "Separate properties and methods"

