sources.en:
classDiagram
    direction TD
    class Customer {
        +String name
        +placeOrder() Order
    }
    class Address {
        +String city
        +String detail
    }
    class Order {
        +String id
        +total() Money
    }
    class OrderItem {
        +int quantity
        +subtotal() Money
    }
    class Product {
        +String title
        +Money price
    }
    class Payment {
        +String status
        +authorize() bool
    }
    class Shipment {
        +String trackingID
        +dispatch()
    }
    Customer --> Order : Created
    Customer --> Address : Save
    Order "1" *-- "1..*" OrderItem
    OrderItem --> Product : Product
    Order --> Payment : Pay
    Payment --> Shipment : Confirm shipment

